    <script type="module">
      const app = document.querySelector('#app');

      async function request(path, options) {
        const response = await fetch(path, options);
        const body = await response.json();
        if (!response.ok) throw new Error(body.error || 'Unable to complete request');
        return body;
      }

      function showError(message) {
        document.querySelector('#error').textContent = message;
      }

      let projects = [];

      function appendProject(project) {
        const row = document.createElement('div');
        row.dataset.testid = 'project-row';
        const name = document.createElement('span');
        name.textContent = project.name;
        const open = document.createElement('button');
        open.textContent = 'Open project';
        open.addEventListener('click', () => {
          location.href = `/projects/${project.id}`;
        });
        const summary = document.createElement('div');
        summary.dataset.testid = 'project-summary';
        summary.className = 'project-summary';
        summary.textContent = `${project.completedCount}/${project.totalCount} completed`;
        const details = document.createElement('div');
        details.className = 'project-details';
        details.append(name, summary);
        const archive = document.createElement('button');
        archive.textContent = project.archived ? 'Restore project' : 'Archive project';
        archive.addEventListener('click', async () => {
          archive.disabled = true;
          showError('');
          try {
            const saved = await request(`/api/projects/${project.id}`, {
              method: 'PATCH',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ archived: !project.archived }),
            });
            projects = projects.map((item) => item.id === saved.id ? saved : item);
            renderProjects();
          } catch (error) {
            showError(error.message);
            archive.disabled = false;
          }
        });
        const actions = document.createElement('div');
        actions.className = 'row-actions';
        actions.append(open, archive);
        row.append(details, actions);
        document.querySelector('#projects').append(row);
      }

      function renderProjects() {
        const archived = document.querySelector('#project-filter').value === 'Archived';
        document.querySelector('#projects').replaceChildren();
        projects.filter((project) => project.archived === archived).forEach(appendProject);
      }

      async function showProjects() {
        app.innerHTML = `
          <h1>Workboard</h1>
          <form>
            <label for="project-name">Project name</label>
            <div class="fields">
              <input id="project-name" name="name" type="text" autocomplete="off">
              <button type="submit" disabled>Create project</button>
            </div>
          </form>
          <div id="error" role="alert"></div>
          <div class="project-filter">
            <label for="project-filter">Project filter</label>
            <select id="project-filter"><option>Active</option><option>Archived</option></select>
          </div>
          <div id="projects"></div>`;
        app.querySelector('#project-filter').addEventListener('change', renderProjects);
        const form = app.querySelector('form');
        const input = app.querySelector('input');
        const submit = form.querySelector('button');
